import type {NarrativeBook,NarrativeChapter,NarrativeSource} from '../../lib/narrativeBooks';
import {classicalHistory,companionHadith} from './companionSources';
const B=(n:string,d:string)=>companionHadith('bukhari',n,d);
const M=(n:string,d:string)=>companionHadith('muslim',n,d);
const caliph=(person:string,name:string)=>classicalHistory(`suyuti-${person}`,'Jalal ad-Din as-Suyuti','Tarikh al-khulafa',`Notice de ${name}`,'https://ar.wikisource.org/wiki/تاريخ_الخلفاء',`Origines, chronologie et succession de ${name} ; les anecdotes ne sont pas reprises indistinctement.`);
const siyar=(id:string,name:string,title:string)=>classicalHistory(`dhahabi-${id}`,'Adh-Dhahabi','Siyar alam an-nubala',`Notice de ${name}`,`https://ar.wikisource.org/wiki/سير_أعلام_النبلاء/${title.replaceAll(' ','_')}`,`Repères de la vie de ${name}. Les divergences de dates sont conservées lorsqu’elles affectent le récit.`);
type Addition={chapter:NarrativeChapter;sources:NarrativeSource[]};
const section=(id:string,title:string,refs:NarrativeSource[],text:string):Addition=>({sources:refs,chapter:{id,title,recap:'',scenes:[{id:`${id}-vie`,title,studyNote:'La chronologie historique et les témoignages de hadith sont identifiés séparément dans les sources.',paragraphs:text.trim().split(/\n\s*\n/u).map(text=>({text,sources:refs.map(r=>r.id)}))}]}});
type Expansion={description:string;before: Addition[];after: Addition[];middle?:{at:number;chapters:Addition[]};keepParagraphs?:number;subtitle:string};
const expansions:Record<string,Expansion>={
 'abu-bakr-confiance':{subtitle:'Les premiers temps de l’islam, l’Hégire et le premier califat',description:'Origines mecquoises, conversion, protection du Prophète, migration, vie médinoise, califat et décès.',before:[
 section('origines','Un homme de La Mecque parmi les premiers croyants',[caliph('abu-bakr','Abu Bakr')],`Abu Bakr est le nom sous lequel la communauté connaît Abdullah ibn Abi Quhafa, issu des Banu Taym de Quraysh. Les notices le situent dans le milieu commerçant de La Mecque. Il appartient à la même société que le Prophète, avant que l’annonce de la révélation ne partage les maisons entre l’accueil et le refus. Sa biographie commence donc avant la grotte et avant le califat : elle est celle d’un homme qui choisit très tôt de croire, lorsque ce choix n’apporte encore ni pouvoir ni sécurité.

Les anciens auteurs le placent parmi les premiers adultes entrés dans l’islam. Ils rapportent son rôle dans l’approche d’autres futurs compagnons, parmi lesquels Uthman, az-Zubayr et Abd ar-Rahman ibn Awf. Ces conversions ne doivent pas être imaginées comme un discours unique dont nous posséderions tous les mots. Elles disent l’importance des liens et de la confiance dans une cité où la prédication se transmet d’abord entre des personnes qui se connaissent.

La nouvelle foi engage aussi ses biens. Les notices attachent son nom à l’affranchissement de croyants réduits en esclavage, dont Bilal. Celui qui aurait pu considérer sa richesse comme une protection personnelle s’en sert pour desserrer une contrainte qui pèse sur un autre. Plus tard, Umar désignera avec respect Abu Bakr et celui qu’il a libéré. La mémoire de Bilal ne se réduit pas à l’aide reçue ; cette aide appartient néanmoins aux actes qui font connaître Abu Bakr dans les premières années.

Les persécutions mettent sa fidélité à l’épreuve bien avant le départ pour Médine. L’adhésion ne reste pas une opinion gardée dans une maison : il intervient lorsqu’il voit le Prophète agressé, envisage lui-même de quitter une ville devenue dangereuse et reçoit un temps une protection tribale. Croire, se montrer et continuer d’adorer deviennent des décisions dont les conséquences touchent son corps, sa famille et son existence quotidienne.`),
 ],middle:{at:1,chapters:[section('medine','Une famille et une fidélité dans les années médinoises',[caliph('abu-bakr','Abu Bakr'),B('3905','Long récit d’Aicha sur les épreuves mecquoises et les préparatifs de l’Hégire.'),B('678','Abu Musa rapporte la demande de faire diriger la priere par Abu Bakr et la reponse d’Aicha.')],`L’Hégire fait d’Abu Bakr un compagnon de route, puis l’un des émigrés qui recommencent leur vie à Médine. La préparation du départ mobilise plusieurs personnes : les montures, le guide, les nouvelles apportées depuis La Mecque et le ravitaillement relient la grotte à la ville. Ses enfants participent à cette organisation. Asma prépare les provisions ; Abdullah rapporte ce qu’il entend. Le voyage que l’on associe à deux noms repose ainsi sur plusieurs responsabilités concrètes.

À Médine, Abu Bakr accompagne le Prophète dans les grands événements de la communauté. Il est présent à Badr et dans les épreuves qui suivent. Sa fille Aicha entre dans le foyer du Messager. Cette proximité familiale ne remplace pas sa place de croyant et de compagnon ; elle fait aussi de lui un père touché par les événements de la maison prophétique. L’épreuve de la calomnie dirigée contre Aicha atteint sa famille, ses relations et son soutien matériel à un proche impliqué dans la rumeur.

Le Coran appelle alors à ne pas renoncer à la générosité envers les proches et les personnes dans le besoin par suite de cette blessure. La tradition rapporte qu’Abu Bakr reprend l’aide qu’il avait interrompue. Sa vie donne ainsi à voir une fidélité qui doit passer par le pardon lorsqu’elle est personnellement éprouvée. Les grands engagements publics ne dispensent pas de ce travail dans les liens ordinaires.

Quand la maladie du Prophète devient grave, Abu Bakr est appelé à diriger la prière. Aicha se souvient de son émotion et de la difficulté qu’elle imagine pour lui à prendre cette place. Ce moment ne peut se lire seulement depuis la suite politique que nous connaissons : il appartient d’abord aux derniers jours du Messager, à une communauté inquiète et à la continuité de la prière. Peu après, Abu Bakr devra porter une responsabilité plus grande encore, au milieu du deuil.`)]},after:[
 section('califat','Maintenir la communauté après la disparition du Messager',[caliph('abu-bakr','Abu Bakr'),B('1399','Discussion avec Umar au sujet du refus de la zakat.'),B('6830','Umar revient sur les événements de l’allégeance à Abu Bakr.')],`Abu Bakr reçoit l’allégeance après les échanges de la Saqifa, puis devant la communauté. Son gouvernement commence en l’an onze de l’Hégire, en 632. Le Prophète est mort ; il ne s’agit pas de lui succéder dans la prophétie, mais de gouverner les affaires des musulmans. Le titre de calife du Messager d’Allah exprime cette distinction. La communauté doit poursuivre son existence alors que celui dont elle recevait directement la direction n’est plus là.

La situation est immédiatement difficile. Différents groupes contestent l’autorité de Médine, certains refusent la zakat et d’autres suivent de nouveaux prétendants à la prophétie. Les chroniques rassemblent ces conflits sous le nom de guerres de la Ridda. Leurs causes ne sont pas toutes identiques. Abu Bakr choisit de maintenir les obligations et l’unité du gouvernement. Umar discute avec lui de la décision de combattre ceux qui refusent la zakat, puis reconnaît la cohérence de sa position.

Ces événements ont lieu dans un cadre politique et militaire précis ; ils ne se transforment pas en autorisation individuelle d’exercer une violence religieuse. Dans le parcours d’Abu Bakr, ils montrent la charge qui lui incombe : il doit décider alors que des territoires et des groupes s’éloignent. La douceur connue chez lui n’exclut pas la fermeté lorsqu’il estime devoir préserver une obligation commune.

Après Yamama, les pertes des dépositaires du Coran ouvrent le travail confié à Zayd ibn Thabit, sur la proposition d’Umar. Dans le même temps, des opérations se développent vers l’Irak et la Syrie. Ce premier califat ne dure qu’un peu plus de deux ans. Sa brièveté ne doit pas masquer ce qu’il traverse : le deuil du Prophète, une crise d’unité, la préservation du Coran et les débuts de changements territoriaux qui se poursuivront après lui.

En l’an treize, en 634, Abu Bakr tombe malade. Il désigne Umar pour prendre la suite, selon la trame conservée par les historiens. Il meurt à Médine et est enterré auprès du Prophète. Les feuillets réunis du Coran passent ensuite à Umar. La vie de l’ancien commerçant de La Mecque s’achève ainsi dans une transmission : il laisse un gouvernement à poursuivre, un travail de préservation à garder et une communauté qui a traversé ses premiers jours sans le Messager.`),
 ]},
 'uthman-transmission':{subtitle:'Des premières migrations au troisième califat',description:'Origines, conversion, famille, exils, vie médinoise, copies du Mushaf, califat et siège de Médine.',before:[
 section('origines','Une foi nouvelle et deux migrations',[caliph('uthman','Uthman ibn Affan'),B('3698','Ibn Umar précise les raisons de l’absence à Badr et les événements de l’allégeance de Ridwan.')],`Uthman ibn Affan appartient aux Banu Umayya de Quraysh. Les notices anciennes le décrivent comme un homme de commerce disposant de ressources. Son entrée dans l’islam est précoce et le rattache au groupe des croyants mecquois avant l’Hégire. La place que sa famille occupe dans la cité n’efface pas les difficultés d’un choix qui s’oppose à la religion dominante. Son avenir ne commence pas dans un palais : il passe par des départs, des deuils et des engagements personnels.

Il épouse Ruqayya, fille du Prophète. Avec elle, il fait partie de ceux qui quittent La Mecque pour l’Abyssinie. La migration permet à des musulmans menacés de chercher un lieu où pratiquer leur foi. Ce premier exil précède celui vers Médine. Il faut donc garder les deux déplacements dans sa vie : Uthman connaît la condition de celui qui laisse sa ville avant de devenir un dirigeant dont des régions entières dépendent.

À Médine, Ruqayya est malade au moment de Badr. Le Prophète demande à Uthman de rester auprès d’elle. Ibn Umar rappellera plus tard cette raison lorsque quelqu’un l’interrogera sur son absence de la bataille. Il reçoit une part de la récompense et du butin, bien qu’il ne soit pas sur le champ de bataille. La sollicitude envers une malade appartient alors à une mission confiée, et non à une désertion que l’on pourrait lui attribuer.

Ruqayya meurt. Uthman épouse ensuite sa sœur Umm Kulthum, elle aussi fille du Prophète. C’est à ces deux unions successives que les notices rattachent son surnom de l’homme aux deux lumières. Le titre prend son sens dans une histoire familiale marquée par les pertes ; il ne doit pas se substituer aux personnes auxquelles il renvoie. La migration, la maladie et le deuil font partie de son parcours autant que les dons qui le rendront célèbre.`),
 ],after:[
 section('califat','Le choix d’Uthman et les années de gouvernement',[caliph('uthman','Uthman ibn Affan'),B('3700','Consultation des six et choix d’Uthman après la mort d’Umar.'),B('912','Ajout d’un appel du vendredi à l’époque d’Uthman devant l’accroissement de la population.')],`À la mort d’Umar, en 23 de l’Hégire, six compagnons ont reçu la mission de consulter pour choisir le dirigeant suivant. Abd ar-Rahman ibn Awf se retire de la candidature et conduit une partie des échanges. Le choix se porte sur Uthman, qui devient le troisième calife en 644. La succession se déroule dans une communauté dont les territoires et les ressources se sont considérablement accrus sous le règne précédent.

Son gouvernement dure environ douze ans. L’expansion se poursuit et les affaires de provinces lointaines prennent une place toujours plus grande. Les chroniques mentionnent les campagnes en Afrique du Nord et le développement des opérations navales. À Médine aussi, la population et les besoins changent. Le témoignage sur l’appel du vendredi rattache à son époque l’ajout d’un appel destiné à avertir plus tôt une cité devenue plus nombreuse.

La préparation des copies de référence du Mushaf s’inscrit dans ce monde élargi. Des populations différentes apprennent et récitent ; Hudhayfa alerte Uthman sur les divergences qu’il a observées. Le calife demande les feuillets de Hafsa et constitue une équipe comprenant Zayd ibn Thabit. La décision ne crée pas un nouveau Coran : elle organise la copie de référence et sa transmission. La part d’Uthman dans cette histoire reste inséparable du travail d’autres compagnons et de ce qui avait été rassemblé avant lui.

Les dernières années du règne connaissent cependant des contestations. Des critiques visent l’administration de certaines provinces, des nominations et l’usage des ressources. Les chroniques présentent des responsabilités, des accusations et des récits qui ne sont pas uniformes. Une biographie honnête ne transforme ni toutes les accusations en faits établis, ni la totalité de cette crise en une seule anecdote. Elle garde le fait d’une opposition croissante et la difficulté d’exercer un gouvernement dont les distances rendent les conflits plus complexes.`),
 section('siege','Le siège de Médine et la mémoire laissée',[caliph('uthman','Uthman ibn Affan'),B('2778','Uthman rappelle les dons du puits de Ruma et de l’armée pendant le siège.')],`Des groupes venus des provinces se trouvent finalement à Médine et le conflit aboutit au siège de la demeure d’Uthman. Le dirigeant qui avait donné de ses biens pour l’eau et les besoins de la communauté se voit menacé au cœur de sa propre ville. Un témoignage conservé par al-Bukhari le montre rappelant aux compagnons ses dons et leur demandant de confirmer ce qu’ils savent. Ces paroles ne sont pas simplement le souvenir d’une richesse ; elles interviennent au milieu d’une rupture présente.

Uthman est tué en l’an trente-cinq de l’Hégire, en 656. Les circonstances particulières du meurtre et le rôle attribué à chaque personne sont rapportés diversement. Il n’est pas nécessaire de reconstituer une scène sanglante ni de choisir des propos invérifiables pour mesurer la gravité de l’événement : un calife est assassiné à Médine et la communauté entre dans une crise dont les suites marqueront le gouvernement d’Ali.

Sa vie avait commencé parmi les premiers convertis, s’était poursuivie dans l’exil et les deuils familiaux, puis dans le don et la transmission. Elle comprend aussi l’exercice d’une autorité contestée. Garder toutes ces périodes ensemble permet de comprendre pourquoi sa mémoire ne se résume ni à l’opulence ni au siège. L’homme qui avait quitté sa ville pour sa foi laisse au premier plan une œuvre collective de préservation dont les générations suivantes continueront de bénéficier.`),
 ]},
 'ali-proximite':{subtitle:'De la maison prophétique au quatrième califat',description:'Enfance et conversion, famille, Hégire, service du Prophète, savoir, califat, conflits et décès.',before:[
 section('origines','Grandir auprès du Prophète',[caliph('ali','Ali ibn Abi Talib')],`Ali est le fils d’Abu Talib, oncle et protecteur du Prophète. Les liens entre les deux hommes précèdent donc la révélation : Ali appartient à cette famille de La Mecque et les notices de la Sira racontent qu’il grandit un temps dans la maison de Muhammad. Il est encore jeune lorsqu’il accueille l’islam. Les auteurs ne fixent pas tous de la même manière son âge précis. Son appartenance aux tout premiers croyants et sa jeunesse sont les repères essentiels de cette entrée dans la foi.

Cette proximité ne donne pas à sa biographie une vie sans rupture. Abu Talib protège le Prophète sans partager sa foi, et l’opposition des Mecquois atteint les croyants jusque dans leurs relations familiales. Ali découvre la nouvelle religion au sein d’un monde où le clan défend parfois une personne tout en refusant ce qu’elle annonce. La fidélité se construit dans cette situation concrète, avant les batailles et avant les responsabilités politiques.

Au moment de l’Hégire, les récits de la Sira attachent à Ali la nuit passée dans le lit du Prophète et le retour des dépôts qui lui avaient été confiés. Ces éléments appartiennent à la tradition biographique ; ils ne permettent pas de fabriquer tous les échanges de cette nuit. Ali rejoint ensuite les émigrés à Médine. La route le conduit d’une maison connue depuis l’enfance à une communauté qui doit désormais organiser ensemble sa vie.

L’histoire familiale se poursuit avec son mariage avec Fatima, fille du Prophète. Leurs enfants, dont al-Hasan et al-Husayn, occupent une place majeure dans la mémoire musulmane. Leur maison est aussi celle du travail et de la fatigue. Les récits domestiques rapportés par Ali montrent cette dimension : être proche du Messager ne supprime pas les efforts du quotidien. La vie du compagnon ne se réduit donc pas au courage public ; elle comprend les obligations d’un époux et d’un père.`),
 ],after:[
 section('savoir','Transmettre et conseiller après le décès du Prophète',[caliph('ali','Ali ibn Abi Talib'),B('4416','Parole à Ali lors de Tabouk, avec l’affirmation qu’il n’y a pas de prophète après Muhammad.')],`La mort du Prophète atteint Ali dans sa foi, dans son affection et dans sa famille. Fatima meurt quelques mois après son père, comme le rapportent les témoignages de cette période. Les années qui suivent placent Ali parmi les compagnons consultés pour leur connaissance et leur jugement. Il ne devient pas immédiatement calife. Sa vie traverse les gouvernements d’Abu Bakr, d’Umar et d’Uthman avant que l’autorité lui soit confiée.

Les notices le présentent comme un dépositaire du savoir, un juriste et un conseiller. Les paroles attribuées à un homme aussi célèbre demandent toutefois un examen particulier : sa mémoire a été entourée de sentences et de récits dont la solidité est inégale. Sa place ne nécessite pas de présenter comme authentique chaque maxime ou chaque exploit spectaculaire diffusé sous son nom. Les témoignages établis suffisent à reconnaître son courage, sa proximité avec le Prophète et sa responsabilité dans la transmission.

Après l’attentat contre Umar, Ali fait partie des six hommes chargés de la consultation pour la succession. Le choix porte alors sur Uthman. Cet épisode doit être situé avant la crise suivante : Ali n’est pas calife pendant les années où se développe l’opposition à Uthman. Une chronologie suivie permet de distinguer ce qu’un conseiller peut faire, ce qu’un dirigeant décide et ce que des groupes accomplissent sans dépendre directement de l’un ou de l’autre.

Lorsque Uthman est assassiné en 656, Ali reçoit à son tour l’allégeance et devient le quatrième calife. La charge commence dans une communauté profondément divisée. Il ne suffit plus de connaître une règle ou de donner un avis : il faut gouverner tandis que le meurtre du calife précédent provoque des demandes de justice et des désaccords sur la manière de rétablir l’ordre.`),
 section('califat','Gouverner au milieu de la première grande crise',[caliph('ali','Ali ibn Abi Talib')],`Le gouvernement d’Ali se déroule entre 35 et 40 de l’Hégire, de 656 à 661. Les événements de cette période sont connus sous le nom de première Fitna. Le conflit du Chameau l’oppose aux forces auxquelles se sont joints Aicha, Talha et az-Zubayr. Plus tard, l’affrontement de Siffin l’oppose à Muawiya et à l’armée de Syrie. Ces noms appartiennent à une histoire douloureuse, qu’on ne peut raconter comme une simple opposition entre personnages sans liens ni passé commun.

Ali établit le centre de son gouvernement à Kufa. Les nécessités militaires, les provinces et la recherche d’un règlement politique occupent ses années de califat. Après Siffin, l’acceptation d’un arbitrage provoque une nouvelle rupture parmi certains de ceux qui l’avaient soutenu. Les kharijites se séparent ; le conflit conduit notamment à Nahrawan. Chaque étape ouvre des conséquences qui ne se confondent pas avec celles de la précédente.

Les chroniques détaillent ces événements avec des récits et des jugements parfois divergents. Ce parcours en garde la succession générale, sans inventer des intentions secrètes ni transformer l’histoire en appel à la haine entre musulmans. Reconnaître la gravité des violences et la dignité des personnes n’exige pas de donner à chaque parole rapportée une certitude qu’elle n’a pas. Ali est à la fois le compagnon de la première communauté et un dirigeant confronté à sa fragmentation.

En l’an quarante de l’Hégire, en 661, il est frappé à Kufa par Ibn Muljam et meurt de sa blessure. Al-Hasan reçoit ensuite l’allégeance d’une partie de ceux qui suivaient son père, avant le règlement qui viendra plus tard. La mort d’Ali clôt sa vie sans faire disparaître immédiatement les conflits. Son héritage demeure dans la transmission du savoir, l’histoire de sa famille et la mémoire d’un gouvernement exercé dans une épreuve extrême.

Du jeune croyant de La Mecque au calife de Kufa, les mêmes noms ne désignent donc pas toujours les mêmes situations. Ali a été un enfant accueilli, un émigré, un époux, un père, un combattant, un transmetteur et un dirigeant. Le comprendre demande de garder ces étapes ensemble. Sa biographie ne gagne rien à être remplacée par une porte arrachée ou une citation sans origine : elle possède déjà la profondeur d’une vie qui traverse les commencements et les premières fractures de la communauté.`),
 ]},
 'khadija-soutien':{subtitle:'Une vie à La Mecque, une confiance au commencement de la révélation',description:'Origines, commerce et mariage, famille, premiers temps de la révélation, difficultés mecquoises, mort et souvenir.',before:[
 section('origines','Une femme de La Mecque avant la révélation',[siyar('khadija','Khadija','خديجة')],`Khadija bint Khuwaylid est issue des Banu Asad de Quraysh. Les notices anciennes la présentent comme une femme de rang, disposant de biens et d’une activité de commerce. Lorsque Muhammad entre dans sa vie, elle a déjà connu le mariage et le veuvage. Le détail de ses unions précédentes et de certains âges varie dans les sources. Sa biographie peut garder ces différences sans les transformer en scène certaine.

Les historiens rattachent leur rencontre à une relation de confiance dans les affaires. Muhammad travaille dans le commerce de Khadija avant leur union. Les récits détaillés du voyage avec Maysara ne présentent pas tous la même force de transmission ; les prodiges ajoutés à cette route ne sont pas nécessaires pour comprendre la place de la confiance dans leur rapprochement. Ce qui se construit est d’abord une maison, bien avant que la révélation n’en fasse le premier refuge du Messager.

Ils se marient à La Mecque. Le Prophète ne prend pas d’autre épouse du vivant de Khadija. Leurs années communes couvrent donc une longue période de sa vie, avant et après l’annonce de la mission. L’âge de quarante ans souvent donné à Khadija au mariage n’est pas l’unique donnée conservée par les auteurs. Nous n’en faisons pas un point indispensable du récit. La durée de la présence et la nature du soutien comptent davantage que le choix arbitraire d’un chiffre discuté.

Leur foyer connaît la naissance des enfants et le deuil. Al-Qasim et Abdullah meurent jeunes ; les filles Zaynab, Ruqayya, Umm Kulthum et Fatima grandissent dans cette famille. Khadija n’est donc pas seulement rencontrée le soir du retour de Hira. Elle est depuis des années une épouse et une mère, engagée dans une vie où la joie et la perte ont déjà leur place. Quand l’événement de la révélation survient, il entre dans une relation qui possède cette histoire.`),
 ],after:[
 section('mecque','Accompagner la mission dans les années difficiles',[siyar('khadija','Khadija','خديجة'),B('3','Accueil du Prophète au retour de Hira et rencontre avec Waraqa.')],`Khadija est la première à accueillir la vérité de la mission. Son aide ne consiste pas à détourner son époux de ce qu’il a reçu, ni à lui promettre que rien ne sera difficile. Elle se souvient de sa manière d’être avec les proches et les personnes vulnérables, puis le conduit auprès de Waraqa pour qu’il puisse raconter ce qui s’est passé. La confiance est ici active : elle écoute, rassemble des raisons de ne pas céder à la peur et cherche une personne capable d’entendre.

L’annonce prophétique ne reste pas longtemps une affaire intérieure à la maison. Le refus de Quraysh, les pressions sur les musulmans et les conflits familiaux transforment les années mecquoises. Les notices de la Sira situent Khadija auprès du Prophète pendant ces difficultés, et notamment durant le boycott imposé aux Banu Hashim et à leurs alliés. La solidarité du clan et la foi des croyants se croisent dans cette épreuve, sans être identiques.

Ces années ne peuvent être reconstruites comme un dialogue continu dont chaque mot nous serait connu. Elles ont pourtant un poids biographique : la femme qui possédait des moyens les engage dans une vie devenue plus exposée ; celle qui avait accueilli la révélation reste présente lorsque l’opposition se durcit. Son soutien ne se réduit donc pas à une consolation unique. Il s’étend à la durée, lorsque la nouveauté a laissé place aux conséquences quotidiennes de l’engagement.

Khadija meurt à La Mecque avant l’Hégire, dans la période que les notices rattachent aussi à la disparition d’Abu Talib. Les auteurs donnent des précisions différentes sur les mois et sur l’ordre exact des deux décès. Le fait essentiel est celui d’une double perte proche : le Prophète ne retrouve plus dans sa maison la présence qui l’avait accueilli au commencement, tandis qu’une importante protection familiale disparaît également. Elle ne connaîtra pas l’installation à Médine.`),
 section('memoire','Une fidélité qui traverse les années',[siyar('khadija','Khadija','خديجة'),B('3818','Souvenir de Khadija, cadeaux envoyés à ses amies et paroles d’Aicha.'),B('3821','La visite de Hala rappelle Khadija au Prophète.')],`Après l’Hégire, la vie du Prophète continue à Médine, mais le nom de Khadija revient dans les souvenirs transmis par Aicha. Celle-ci ne l’a pas connue comme épouse présente dans la maison médinoise. Elle entend pourtant combien elle demeure dans la mémoire du Messager. Lorsqu’une bête est sacrifiée, de la viande peut être envoyée aux amies de Khadija. La fidélité garde ainsi une forme concrète : elle rejoint des personnes que la disparue aimait.

La voix de Hala, sa sœur, rappelle un jour à son oreille celle de Khadija. Le témoignage conserve ce mouvement de reconnaissance. Il ne s’agit pas de décrire à notre façon l’invisible ou d’ajouter des paroles à un deuil ancien. Ce souvenir suffit à laisser entendre qu’une relation ne disparaît pas de la vie d’un homme au moment où la personne aimée n’y est plus physiquement présente.

L’annonce d’une demeure au Paradis et le salut transmis par Jibril appartiennent aux témoignages sur son mérite. Ils ne nous donnent pas à représenter cette demeure comme un décor historique que l’on pourrait décrire librement. À côté de ces annonces, les actes de sa vie restent lisibles : le commerce, le foyer, l’accueil de la révélation et la présence dans la difficulté.

Son parcours s’achève avant la grande transformation médinoise et avant les conquêtes auxquelles l’islam sera ensuite associé. Elle a cru et soutenu alors que ces résultats n’étaient pas devant elle. C’est cette durée qu’une biographie doit restituer. Khadija ne devient pas un personnage secondaire parce que sa vie est principalement connue par une maison et un soutien : cette maison fut l’un des lieux où la mission a pu être entendue, reconnue et portée.`),
 ]},
 'bilal-dignite':{subtitle:'De l’esclavage à La Mecque à la voix de la communauté',description:'Origines, persécutions, affranchissement, Hégire, adhan, vie auprès du Prophète et dernières années en Syrie.',before:[
 section('origines','La foi d’un homme que l’on voudrait réduire au silence',[siyar('bilal','Bilal ibn Rabah','بلال بن رباح'),B('3754','Umar rappelle qu’Abu Bakr a affranchi Bilal.')],`Bilal ibn Rabah fait partie des premiers musulmans. Les notices le connaissent comme un homme d’origine abyssinienne, lié à La Mecque par la condition servile dans laquelle il vit. Elles nomment sa mère Hamama et rapportent des indications différentes sur son lieu de naissance. Sa vie ne peut donc être racontée comme s’il nous avait laissé une généalogie et un journal d’enfance complets. Ce que les témoignages font apparaître avec force est la violence qu’il subit pour sa foi et la place qu’il prendra ensuite dans la communauté.

À La Mecque, ceux qui ne disposent pas d’une protection de clan sont particulièrement exposés. Bilal est torturé pour qu’il renonce à l’islam. Les biographies anciennes conservent le souvenir de son affirmation de l’unicité d’Allah au milieu de cette épreuve. Il ne s’agit pas d’un décor destiné à embellir son destin futur : la contrainte s’exerce sur une personne dont d’autres disposent alors comme d’un bien. Sa résistance porte sa foi dans les limites mêmes où l’on cherche à l’enfermer.

Abu Bakr l’achète et l’affranchit. Les détails du prix ne sont pas identiques dans tous les récits et ne décident pas du sens de l’événement. Bilal devient libre. Bien plus tard, Umar rappellera avec respect qu’Abu Bakr est celui qui a affranchi cet homme qu’il appelle lui aussi son maître. La mémoire conservée ne célèbre pas seulement un bienfaiteur ; elle reconnaît la dignité et le rang de celui qui avait été possédé.

L’affranchissement ne clôt pas sa vie. Une biographie qui s’arrêterait à la torture laisserait Bilal dans la seule place de victime. Il continue à apprendre, à se déplacer avec les croyants et à servir la communauté. L’homme que l’on voulait empêcher de confesser sa foi deviendra précisément l’une des voix par lesquelles les musulmans se retrouveront pour prier.`),
 section('hijra','Recommencer à Médine',[siyar('bilal','Bilal ibn Rabah','بلال بن رباح'),B('3925','Arrivée de Bilal parmi les émigrés avant celle du Prophète.'),B('1889','Aicha rapporte la maladie des émigrés et les paroles de Bilal sur La Mecque.')],`Bilal émigre à Médine. Al-Bara ibn Azib le nomme parmi ceux qui arrivent avant le Prophète. Comme les autres émigrés, il laisse un lieu familier pour une communauté qui se rassemble ailleurs. Les années mecquoises l’ont exposé à la violence, mais elles ont aussi formé son expérience d’une ville qu’il connaît. Partir ne signifie pas ne plus rien y avoir vécu ni ressenti.

Un témoignage d’Aicha rapporte les fièvres qui touchent Abu Bakr et Bilal après l’installation. Elle entend les paroles où Bilal se souvient des lieux de La Mecque. Le souvenir du pays quitté se mêle à l’épuisement de la maladie. Le Prophète invoque pour que Médine devienne aimée des émigrés et pour que son climat leur soit favorable. La grande migration possède ainsi une dimension très humaine : des corps doivent s’habituer, des attachements demeurent et une nouvelle ville doit devenir un foyer.

Bilal participe à Badr et aux autres événements de la communauté, comme le mentionnent ses notices biographiques. Son service auprès du Messager ne se limite pas à un instant spectaculaire. La prière, les voyages et les besoins ordinaires le placent régulièrement dans cet entourage. Son passé n’a pas disparu, mais il ne fixe plus la fonction que d’autres lui imposent. Il exerce désormais des responsabilités qui le font connaître pour sa foi et pour sa présence.

C’est dans ce cadre que l’adhan prend sa place. L’appel organise le temps commun et invite les personnes dispersées à se réunir. Celui qui le prononce sert l’adoration de tous. Pour entendre la portée de cette mission dans la vie de Bilal, il faut garder le chemin déjà parcouru : le croyant persécuté de La Mecque, l’homme affranchi et l’émigré malade sont aussi celui dont la voix rassemble maintenant les musulmans.`),
 ],after:[
 section('syrie','Après le Prophète, la route vers la Syrie',[siyar('bilal','Bilal ibn Rabah','بلال بن رباح')],`La mort du Prophète ouvre une rupture pour Bilal comme pour les autres compagnons. Les notices biographiques le retrouvent ensuite en Syrie. Il ne faut pas réduire tout ce qui suit à la seule image d’un appel qu’il aurait été incapable de prononcer : les versions sur ses déplacements et sur les occasions où il appelle de nouveau ne possèdent pas toutes la même solidité. Le fait de sa présence en Syrie appartient aux grands repères de la fin de sa vie.

Il demeure un témoin du Messager. Des compagnons et des membres de la génération suivante rapportent ce qu’ils ont reçu de lui. Sa mémoire porte l’appel à la prière, mais aussi des paroles et des pratiques observées au contact du Prophète. Cette transmission est une autre manière de rester au service de la communauté. Une voix peut être connue de tous et laisser aussi derrière elle un savoir confié à quelques auditeurs.

Les historiens donnent plusieurs indications sur la date et le lieu précis de son décès ; une tradition le situe dans la région de Damas, autour de l’an vingt de l’Hégire. Plutôt que d’imposer à tous les récits une exactitude qu’ils ne partagent pas, nous gardons ce cadre et ces différences. La fin de Bilal se trouve dans une communauté et un territoire qui ont changé depuis ses débuts mecquois.

Son parcours relie la privation de liberté, l’affranchissement, l’exil et une responsabilité reconnue. Il ne devient pas digne au moment où on lui confie l’adhan : cette dignité était déjà la sienne lorsque d’autres prétendaient disposer de lui. La vie après l’épreuve permet de le voir pleinement, comme un croyant, un compagnon et un transmetteur.`),
 ]},
 'musab-transmettre':{subtitle:'De la jeunesse mecquoise à l’enseignement de Médine et à Uhud',description:'Milieu familial, conversion, épreuves mecquoises, migration et enseignement, Uhud et témoignages laissés.',before:[
 section('origines','Un jeune Mecquois choisit une autre vie',[siyar('musab','Musab ibn Umayr','مصعب بن عمير'),classicalHistory('ibnhisham-abyssinie','Ibn Hisham','As-Sira an-nabawiyya','Premiere migration vers l’Abyssinie','https://islamwww.com/wp-content/uploads/2018/10/siratibnhsham.pdf','Liste ancienne des emigres : Musab, Uthman et Ruqayya, Abu Salama et Umm Salama ; texte ancien, ajouts editoriaux modernes non repris.')],`Musab ibn Umayr appartient aux Banu Abd ad-Dar de Quraysh. Les biographies anciennes le présentent comme un jeune homme élevé dans l’aisance à La Mecque. Son nom sera ensuite associé à l’étoffe trop courte qui servira de linceul. Mais commencer par cette seule image ferait disparaître le chemin qui la précède : Musab n’a pas toujours connu la pauvreté sous laquelle ses compagnons se souviendront de lui.

Il accueille l’islam dans les premiers temps de la prédication. Les récits de la Sira décrivent la rupture provoquée dans son milieu familial et les contraintes imposées pour le détourner de cette foi. Le contraste entre le confort de sa jeunesse et la difficulté de ses nouvelles conditions traverse ses notices. Il ne faut pas le remplacer par la description imaginaire d’une chambre, d’un vêtement ou d’une conversation avec sa mère. Le changement de vie est déjà assez profond sans ces ajouts.

Son appartenance à une famille reconnue ne lui permet pas de conserver simplement toutes ses habitudes avec une conviction nouvelle. Le choix religieux modifie ce qu’il peut attendre des siens et les moyens dont il dispose. Il rejoint le sort d’autres croyants qui apprennent à vivre avec la pression, l’éloignement et la réduction de leurs ressources. La foi devient un engagement dont les conséquences se mesurent dans les journées ordinaires.

Les traditions biographiques le rattachent aussi aux migrations des premiers musulmans vers l’Abyssinie. Ces départs donnent aux croyants menacés un espace où vivre leur foi. Ils rappellent que l’avenir médinois n’était pas encore le chemin visible de toute la communauté. Musab traverse les étapes d’une première génération qui doit parfois quitter sa ville avant de savoir où elle pourra s’établir durablement.`),
 section('mission','Préparer des personnes à recevoir le message',[siyar('musab','Musab ibn Umayr','مصعب بن عمير'),B('3925','Musab et Ibn Umm Maktum enseignent le Coran à Médine avant l’arrivée du Prophète.')],`Avant l’installation du Prophète à Médine, Musab reçoit une mission d’enseignement auprès des nouveaux croyants de Yathrib. La tradition de la Sira le présente aux côtés de ceux qui préparent cette ville à l’accueil des émigrés. Le témoignage d’al-Bara confirme le cœur de cette présence : Musab et Ibn Umm Maktum enseignent le Coran avant l’arrivée du Messager. Sa biographie passe alors de ce qu’il a quitté à ce qu’il va transmettre.

Enseigner dans une ville traversée par des liens de familles et de tribus exige davantage qu’une connaissance récitée pour soi. Il faut rencontrer des personnes, leur faire entendre le message et permettre à d’autres de l’apprendre à leur tour. Les notices de la Sira relatent notamment l’accueil de familles médinoises et des conversions qui agrandissent le groupe. Nous gardons cette progression sans reconstruire chaque discussion ni lui prêter à lui seul l’ensemble de ce qui change dans la ville.

Le rôle de Musab se comprend ainsi dans un travail collectif. Des Médinois ont accueilli la foi, d’autres la découvrent, et les personnes venues de La Mecque préparent une nouvelle étape. L’enseignement donne une continuité à ces liens : ce qui est reçu ne reste pas attaché à la présence d’un seul voyageur. Les auditeurs apprennent et deviennent capables de transmettre.

Lorsque l’Hégire conduit ensuite le Prophète à Médine, l’accueil se prépare donc depuis un certain temps. Musab a contribué à ce commencement. L’homme dont la vie sera courte n’a pas pour autant une histoire réduite à son dernier combat : son passage dans une ville en transformation a laissé des croyants qui continueront après lui. Son service consiste aussi à faire grandir ce qu’il ne sera pas là pour voir entièrement.`),
 ],after:[
 section('parcours','Une vie courte, une transmission qui demeure',[siyar('musab','Musab ibn Umayr','مصعب بن عمير'),B('1276','Khabbab rapporte la mort de Musab à Uhud et la difficulté de le couvrir.')],`Musab participe à Badr, puis meurt à Uhud, en l’an trois de l’Hégire, en 625. La tradition biographique lui confie l’étendard au cours de cette bataille et rapporte son engagement auprès du Prophète. Les descriptions détaillées de ses blessures ne sont pas toutes reçues par les mêmes voies ; la biographie n’a pas besoin d’en faire une scène spectaculaire. Le témoignage de Khabbab laisse une image sobre et sûre : les compagnons cherchent à couvrir un mort qui ne possède qu’une étoffe insuffisante.

Cette fin doit rester reliée aux années de la jeunesse, au choix de l’islam, aux départs et à la mission d’enseignant. Le manque de biens au moment du décès n’est pas toute l’identité de Musab. Il est le point où des témoins mesurent ce qu’il a donné sans avoir connu l’aisance qui viendra à d’autres. Abd ar-Rahman ibn Awf se souviendra de lui lorsqu’un repas lui sera servi bien plus tard.

Sa vie ne comporte pas les décennies de transmission d’un Anas ou d’un Ibn Umar. Elle n’a pas à être artificiellement prolongée pour leur ressembler. Le parcours connu possède sa continuité propre : une foi choisie, des conditions transformées, des personnes instruites et une présence jusqu’à Uhud. Ceux qui ont appris à Médine et ceux qui racontent ensuite sa fin gardent ensemble les traces de cette vie.`),
 ]},
 'zayd-thabit-confie':{subtitle:'Un jeune Médinois, le scribe et le savant de la transmission',description:'Origines médinoises, apprentissage, écriture de la révélation, recueils du Coran, savoir juridique et dernières années.',before:[
 section('origines','Un enfant de Médine au commencement d’une nouvelle époque',[siyar('zayd-thabit','Zayd ibn Thabit','زيد بن ثابت')],`Zayd ibn Thabit n’est pas un émigré de La Mecque. Il appartient aux Banu Najjar, parmi les Khazraj de Médine. Les notices rapportent qu’il a perdu son père lors de Buath, avant l’Hégire. La ville dans laquelle il grandit porte donc une histoire de conflits antérieurs à l’arrivée du Prophète. Quand les émigrés viennent s’y établir, Zayd est encore très jeune ; la biographie d’adh-Dhahabi conserve l’indication d’environ onze ans.

Le jeune Médinois apprend le Coran et dispose de capacités d’écriture. Les récits rapportent qu’il est présenté au Prophète et qu’un apprentissage lui est confié pour les besoins de la correspondance. Ce début permet de comprendre le chemin du futur scribe : une aptitude devient utile parce qu’elle est cultivée et placée au service d’une responsabilité. Le travail qui le fera connaître plus tard ne tombe pas sur un homme que rien n’y aurait préparé.

Sa jeunesse lui donne une place différente de celle des compagnons déjà adultes à La Mecque. Il ne porte pas les mêmes souvenirs et n’a pas participé aux mêmes premières épreuves. En revanche, il grandit à proximité de la communauté médinoise et voit ses besoins changer. L’histoire du Coran conservé passe ainsi par des générations qui se rencontrent : les premiers croyants, des émigrés, des Ansar et de jeunes personnes formées au milieu d’eux.

Zayd est connu parmi les scribes de la révélation. Ce titre ne signifie pas qu’il serait l’unique personne à écrire ni qu’il aurait reçu une révélation personnelle. Il travaille pour le Messager et conservera le souvenir de tâches précises. Cette distinction est essentielle pour entendre ce qu’Abu Bakr et Umar lui demanderont ensuite : ils s’adressent à un jeune homme dont la probité, l’intelligence et l’expérience de l’écriture sont déjà reconnues.`),
 ],after:[
 section('savant','Le savoir ne s’arrête pas à la dernière copie',[siyar('zayd-thabit','Zayd ibn Thabit','زيد بن ثابت')],`Zayd reste une figure majeure de Médine après le travail des feuillets et des copies. Les notices le présentent comme un savant du Coran, de la récitation et des règles successorales. Umar lui confie aussi des responsabilités dans la ville pendant certaines absences. La confiance accordée au scribe devient donc une confiance dans un homme capable de juger et de conseiller ; sa vie ne s’achève pas lorsque le manuscrit a été remis à son gardien.

Des compagnons et des membres de la génération suivante reçoivent son enseignement. Les auteurs citent notamment Ibn Abbas, Abu Hurayra et son fils Kharija parmi ceux qui transmettent de lui, avec des relations d’apprentissage différentes selon les personnes. Le savoir successoral demande une attention aux liens familiaux, aux droits et aux calculs ; il donne à la transmission une portée très concrète dans la vie de ceux qui viennent consulter.

Ce prolongement éclaire aussi les travaux précédents. La rigueur de Zayd ne concerne pas seulement un objet prestigieux appelé Mushaf. Elle s’inscrit dans une manière de recevoir, de vérifier et de transmettre un savoir auquel d’autres devront pouvoir se fier. Les paroles conservées dans les notices à sa mort expriment le sentiment qu’une part importante de cette connaissance vient de perdre l’un de ses dépositaires.

Les historiens diffèrent sur l’année exacte de son décès. Sa mort se situe à Médine, plusieurs décennies après l’Hégire. Nous ne choisissons pas une date unique pour effacer cette diversité de transmission. Ce qui demeure dans l’ensemble de son parcours est un changement d’échelle : un enfant d’une cité marquée par ses propres conflits devient le scribe puis le savant auquel la communauté confie des responsabilités essentielles.

Le Coran n’a pas été inventé par celui qui le rassemble. Zayd lui-même a éprouvé la gravité de cette mission. Le suivre depuis sa jeunesse jusqu’à l’enseignement permet d’entendre ce que son travail avait de personnel et de collectif : une compétence réelle, une conscience du dépôt et le concours de nombreux autres témoins.`),
 ]},
 'asma-liens':{subtitle:'De la maison d’Abu Bakr aux dernières années d’une mère',description:'Famille, premiers temps de l’islam, préparation de l’Hégire, migration, maternité, vie médinoise et épreuve d’Abdullah ibn az-Zubayr.',before:[
 section('origines','Deux sœurs, une maison et des chemins différents',[siyar('asma','Asma bint Abi Bakr','أسماء بنت أبي بكر')],`Asma est la fille d’Abu Bakr et de Qutayla. Elle est la sœur aînée d’Aicha par leur père. Les deux femmes partagent une famille, mais leurs histoires ne se confondent pas : Asma devient l’épouse d’az-Zubayr ibn al-Awwam et la mère d’Abdullah et d’Urwa. Sa vie traversera une période beaucoup plus longue que les premiers départs de La Mecque auxquels on associe souvent son nom.

Elle accueille l’islam dans les années mecquoises. Dans la maison d’Abu Bakr, la foi du père et celle des enfants prennent place au milieu d’une cité qui exerce des pressions sur les croyants. Quand le départ du Prophète et d’Abu Bakr se prépare, Asma est donc déjà une personne engagée dans cette histoire. Elle ne se trouve pas simplement devant une scène héroïque qui lui donnerait soudain une identité.

Les provisions et le lien découpé pour les attacher lui valent le surnom de la femme aux deux ceintures. Le geste est devenu célèbre parce qu’il apporte une solution pratique au moment nécessaire. Il appartient toutefois à une préparation plus vaste, qui comprend des montures, un guide et la circulation des nouvelles. La part d’Asma est importante sans avoir besoin d’effacer celles des autres.

Son nom invite ainsi à regarder les personnes qui rendent un départ possible sans être au premier plan de la route elle-même. Mais sa biographie doit ensuite quitter ce seul moment. L’Hégire sera aussi son propre voyage, sa maternité, son travail et l’entrée dans une ville où elle devra construire sa vie.`),
 ],middle:{at:1,chapters:[section('maternite','Traverser enceinte et faire sa place à Médine',[siyar('asma','Asma bint Abi Bakr','أسماء بنت أبي بكر'),B('3909','Asma émigre enceinte et donne naissance à Abdullah à Quba.')],`Asma quitte La Mecque alors qu’elle attend Abdullah. Elle arrive à Quba, aux abords de Médine, où elle donne naissance à son fils. Son témoignage rapporte qu’elle le porte ensuite au Prophète. La naissance est accueillie dans la communauté des émigrés et garde une place particulière dans leur mémoire. La migration n’est donc pas seulement un mouvement d’hommes adultes ; elle concerne aussi une femme enceinte et un enfant qui commence sa vie dans ce nouvel environnement.

Le père d’Abdullah est az-Zubayr, dont les moyens sont encore modestes. Asma décrit les tâches qu’elle accomplit dans leur maison et pour leurs biens : le cheval, la nourriture à préparer, l’eau et les noyaux de dattes à transporter. Ces détails permettent d’entendre ce que recommencer signifie pour elle. La dignité de la compagne n’efface ni la charge physique ni le besoin d’un soutien concret.

Ses rapports avec sa mère demeurent également dans les témoignages. Qutayla n’a pas alors la même religion qu’elle. Asma interroge le Prophète sur la manière de maintenir le lien et reçoit la permission de lui faire du bien. La vie familiale ne devient donc pas une ligne simple où chacun suivrait immédiatement la même route. Elle demande de tenir ensemble la foi choisie et les obligations de bonté envers une mère.

La famille qui grandit transmettra aussi. Urwa ibn az-Zubayr et des proches feront connaître ses souvenirs. Ce qu’Asma raconte des préparatifs, du travail et des relations passe ainsi à une génération qui n’a pas vécu elle-même ces événements. Sa longue vie fera d’elle l’une des dernières voix des premières émigrées.`)]},after:[
 section('derniers-jours','Une mère face au sort de son fils',[siyar('asma','Asma bint Abi Bakr','أسماء بنت أبي بكر'),M('2545','Mort d’Abdullah ibn az-Zubayr, visite d’al-Hajjaj et réponse d’Asma.')],`Asma vit assez longtemps pour connaître les bouleversements qui suivent les premiers califats. Son fils Abdullah ibn az-Zubayr prend une place politique majeure et reçoit l’allégeance dans une partie du monde musulman, en opposition au pouvoir omeyyade. Sa mère se trouve ainsi liée à un conflit qui dépasse largement les années de son installation à Médine. Les liens construits au commencement de sa vie sont maintenant éprouvés dans une autre époque.

En l’an soixante-treize de l’Hégire, Abdullah est tué à La Mecque après le siège mené par al-Hajjaj. Le témoignage conservé par Muslim rapporte l’exposition de son corps et la rencontre ultérieure d’Asma avec al-Hajjaj. Elle ne reçoit pas sa prétention à avoir tranché l’honneur de son fils comme une vérité qu’elle devrait répéter. Sa réponse demeure celle d’une mère âgée qui parle devant le représentant du pouvoir ayant fait tuer son enfant.

Une biographie n’a pas à transformer cette scène en spectacle ni à reconstruire les conseils mot pour mot au-delà des témoignages disponibles. Elle doit en conserver la portée : la femme qui préparait autrefois un départ affronte désormais la mort publique de son fils. La même vie traverse des changements politiques, des liens familiaux et une douleur qu’un simple surnom héroïque ne peut contenir.

Les notices situent la mort d’Asma peu après celle d’Abdullah. Elles insistent sur sa longévité. Les estimations d’âge exactes dépendent de repères qui ne sont pas tous identiques ; l’essentiel est qu’elle appartient encore par sa mémoire au temps de La Mecque et de l’Hégire, tout en ayant vu les générations suivantes prendre des chemins nouveaux. Son récit relie ainsi le commencement d’une communauté à l’épreuve de ce qu’elle devient.`),
 ]},
 'umm-salama-sagesse':{subtitle:'Les exils, le deuil et une vie de transmission',description:'Famille mecquoise, migrations, enfants, veuvage, mariage avec le Prophète, Hudaybiyya et enseignement.',before:[
 section('origines','Une première famille au temps des départs',[siyar('umm-salama','Umm Salama','أم سلمة'),classicalHistory('ibnhisham-abyssinie','Ibn Hisham','As-Sira an-nabawiyya','Premiere migration vers l’Abyssinie','https://islamwww.com/wp-content/uploads/2018/10/siratibnhsham.pdf','Liste ancienne des emigres : Musab, Uthman et Ruqayya, Abu Salama et Umm Salama ; texte ancien, ajouts editoriaux modernes non repris.')],`Umm Salama se nomme Hind bint Abi Umayya. Elle appartient aux Banu Makhzum de Quraysh. Son premier mari, Abu Salama ibn Abd al-Asad, fait partie des premiers musulmans. Avant qu’elle soit connue comme épouse du Prophète, elle a donc déjà une histoire de foi, de mariage, d’enfants et de départs. Sa vie ne commence pas au moment où un nouveau foyer lui est proposé.

Les notices la comptent parmi les premières émigrées. Avec Abu Salama, elle connaît le départ vers l’Abyssinie, puis les difficultés du chemin vers Médine. Les récits de séparation familiale qui accompagnent cette période appartiennent à la tradition de la Sira ; leurs détails ne doivent pas être récités comme s’ils avaient tous été transmis de la même manière. Le fait de ces migrations suffit déjà à rappeler une vie déplacée plusieurs fois pour pouvoir garder la foi.

L’exil ne concerne pas seulement un couple. Des enfants doivent être protégés et une famille doit retrouver une place dans chaque nouvel environnement. Les noms de Salama, Umar et Zaynab apparaîtront ensuite dans la transmission de cette maison. Ceux qui seront plus tard des témoins ont d’abord été de jeunes personnes dépendant des décisions et des épreuves de leurs parents.

À Médine, Abu Salama participe à la vie de la communauté et connaît les blessures du combat. Les sources biographiques rattachent sa mort aux suites d’une blessure. Pour Umm Salama, le deuil se présente donc après les ruptures déjà traversées. La parole d’invocation qu’elle rapporte dans le recueil de Muslim entre dans cette histoire, avec le nom d’un époux réel et la responsabilité de ceux qui restent.

Lorsqu’elle se souvient qu’elle ne voyait pas quel homme pourrait être meilleur qu’Abu Salama, elle ne prononce pas une formule vide destinée à préparer une fin heureuse. Elle mesure ce qu’elle vient de perdre depuis la vie qu’ils ont déjà construite. La suite n’efface pas cette première famille ; elle va devoir lui faire une place.`),
 ],after:[
 section('transmission','Une mère des croyants que l’on vient interroger',[siyar('umm-salama','Umm Salama','أم سلمة'),M('330a','Question d’Umm Salama au Prophète sur les tresses et la purification.')],`Le mariage d’Umm Salama avec le Prophète est généralement situé en l’an quatre de l’Hégire. Les traditions gardent les préoccupations qu’elle exprime au sujet de ses enfants et de sa propre situation. Son entrée dans cette maison ne signifie pas qu’elle abandonne les responsabilités de sa première vie. Elle devient une mère des croyants avec une expérience de l’exil, du mariage et du deuil qu’aucune autre personne ne peut simplement vivre à sa place.

Le conseil qu’elle donne à Hudaybiyya rend visible sa capacité à comprendre une situation collective difficile. Lorsque les compagnons tardent à accomplir les gestes demandés après l’accord, elle invite le Prophète à les accomplir lui-même. Les autres le suivent. Sa parole ne se substitue pas à la mission prophétique : elle apporte un conseil reçu dans une situation précise. Une biographie qui ne garderait que la scène perdrait toutefois la vie déjà traversée par celle qui sait écouter et proposer.

Elle transmet aussi des enseignements sur la prière, la purification et la vie du Messager. Un témoignage de Muslim la montre posant une question concrète au sujet de ses tresses et de la purification. L’interrogation d’une femme sur sa pratique entre ainsi dans le savoir conservé par toute la communauté. Les auditeurs qui viennent ensuite auprès d’elle reçoivent à la fois des paroles et l’expérience d’un témoin du foyer prophétique.

Après la mort du Prophète, Umm Salama demeure longtemps à Médine. Des personnes des générations suivantes prennent auprès d’elle ce qu’elles n’ont pas pu entendre directement du Messager. Les dates de son décès divergent dans les notices, qui la placent parmi les dernières épouses du Prophète à disparaître. Cette longévité donne à sa biographie une dernière période essentielle : elle n’est pas seulement celle qui a conseillé un jour, mais celle qui a continué à transmettre durant des décennies.

Son parcours garde ensemble plusieurs vies que l’on sépare trop vite : l’épouse d’Abu Salama, la mère, l’émigrée, la veuve, la mère des croyants et l’enseignante. Les noms et les étapes permettent de la connaître avec davantage de précision qu’une seule qualité appelée sagesse. Cette sagesse se lit au milieu des responsabilités, des pertes et des personnes qu’elle n’a pas cessé d’accompagner.`),
 ]},
 'aicha-innocence':{subtitle:'Une vie de savoir, d’épreuves et de transmission',description:'Famille mecquoise, vie médinoise, épreuve de la calomnie, enseignement, événements du Chameau et dernières années.',keepParagraphs:3,before:[
 section('origines','La fille d’Abu Bakr dans les premières années de l’islam',[B('3905','Aicha rapporte ne connaître ses parents que pratiquant l’islam et décrit l’Hégire.'),B('5134','Témoignage d’Aicha sur son mariage et son arrivée dans le foyer prophétique.')],`Aicha est la fille d’Abu Bakr et d’Umm Ruman. Elle naît à La Mecque dans une famille qui a déjà accueilli l’islam. Son témoignage rapporte qu’elle n’a connu ses parents que pratiquant cette religion. Elle grandit donc au contact de l’engagement de son père, des visites du Prophète et des pressions exercées sur les croyants. Son enfance ne possède pas les mêmes souvenirs que celle des compagnons entrés dans l’islam à l’âge adulte.

Elle raconte les préparatifs de l’Hégire avec une précision qui fera d’elle l’une des grandes dépositaires de cette mémoire familiale. Elle connaît les personnes, les montures et les précautions entourant le départ. Les souvenirs d’une maison entrent ainsi dans l’histoire générale de la communauté. La personne qui racontera plus tard l’épreuve de la calomnie est déjà une observatrice et une narratrice de ce commencement.

Son mariage avec le Prophète est conclu avant l’Hégire et sa vie dans son foyer commence à Médine. Le témoignage reçu dans le recueil d’al-Bukhari situe le mariage conclu à six ans et l’entrée dans le foyer à neuf ans. Il rattache ces étapes aux dernières années mecquoises, puis à l’installation médinoise. Sa biographie doit ensuite suivre ce qu’elle apprend, ce qu’elle traverse et ce qu’elle transmet, au lieu de s’arrêter à cette seule indication.

La maison prophétique devient pour elle un lieu d’observation de l’adoration, des relations et des pratiques quotidiennes. Tout ce que les croyants veulent connaître ne se déroule pas sur une place publique. Sa position permettra de faire entendre des enseignements auxquels les témoins extérieurs n’assistent pas. Mais cette proximité ne lui épargne ni les émotions, ni la maladie, ni l’épreuve de paroles fausses dirigées contre elle.`),
 ],after:[
 section('savoir','Entendre, demander et corriger',[B('103','Aicha demande une explication sur le jugement des actes au Jour dernier.'),B('2026','Aicha rapporte la retraite spirituelle du Prophète et celle de ses épouses après lui.'),B('3770','Anas rapporte une parole du Prophete sur la place d’Aicha.')],`Après la mort du Prophète, Aicha continue à enseigner. Les personnes qui viennent l’interroger ne cherchent pas seulement le souvenir d’une épouse : elles reçoivent une connaissance de l’adoration, de la vie du Messager et de la compréhension des paroles transmises. Des membres de sa famille, dont Urwa ibn az-Zubayr et al-Qasim ibn Muhammad, ainsi que d’autres auditeurs, feront circuler ce savoir dans la génération suivante.

Sa manière d’apprendre se voit dans ses propres questions. Lorsqu’une parole lui semble demander une précision, elle ne se contente pas de la retenir sans chercher à comprendre. Un témoignage d’al-Bukhari rapporte notamment son interrogation sur le fait de rendre compte de ses actes, rapprochée d’un passage coranique. La réponse distingue la présentation des actes d’un examen qui conduit au châtiment. Une question attentive devient ainsi utile aux auditeurs qui la recevront ensuite.

Son témoignage garde également des pratiques qui continuent après le décès du Messager. Elle rapporte que ses épouses poursuivent la retraite spirituelle qu’il accomplissait. La transmission ne consiste donc pas seulement à décrire un passé inaccessible : elle peut aussi montrer comment un enseignement est gardé dans le présent d’une communauté qui doit désormais vivre sans sa présence.

Aicha est l’une des principales transmettrices du hadith. La diversité des sujets qu’elle aborde empêche de l’enfermer dans la seule épreuve de la calomnie. Cette épreuve demeure une partie importante de sa vie, mais elle ne remplace ni son activité intellectuelle, ni sa pratique, ni les décennies pendant lesquelles d’autres apprennent auprès d’elle. Son récit personnel devient une source ; elle-même reste une enseignante au-delà de ce récit.`),
 section('derniers-jours','Les crises de la communauté et les années de Médine',[caliph('ali','Ali ibn Abi Talib'),classicalHistory('ibnhajar-aicha','Ibn Hajar al-Asqalani','Al-Isaba fi tamyiz as-sahaba','Notice d’Aicha bint Abi Bakr','https://www.ibnalarabi.com/tarajim/tarjamat.php?id=9465','Notice ancienne reproduite avec plusieurs extraits biographiques : transmission et variantes sur l’année du décès.')],`La vie d’Aicha traverse les gouvernements des premiers califes puis la crise ouverte par l’assassinat d’Uthman. En l’an trente-six de l’Hégire, en 656, elle se trouve au centre des événements qui conduisent à l’affrontement du Chameau, avec Talha et az-Zubayr, face au gouvernement d’Ali. Cette participation appartient à son histoire. Elle ne doit être ni effacée, ni transformée en une succession de discours et d’intentions que nous inventerions.

Les chroniques exposent les désaccords sur le rétablissement de l’ordre et la justice après le meurtre du calife. Les personnes engagées avaient une histoire commune avec le Prophète ; l’affrontement n’en est que plus douloureux. Après les combats, Aicha retourne à Médine. La trame biographique garde ce retour sans faire d’une période de conflit la mesure unique de tout ce qu’elle a vécu et transmis.

À Médine, son enseignement se poursuit. Son savoir rejoint des personnes qui n’ont pas connu le Messager, puis leurs élèves. Les événements publics ne suppriment donc pas les dernières décennies de sa vie. C’est aussi dans cette durée que se forme l’héritage qu’on associe à son nom : une connaissance conservée, interrogée et transmise, et non le seul souvenir d’un épisode politique ou d’une accusation subie.

Les notices anciennes situent sa mort à Médine à la fin des années cinquante de l’Hégire, souvent en 58, avec une variante en 57. Elle est enterrée à al-Baqi. Le témoignage d’une fille de la maison d’Abu Bakr a alors rejoint celui d’une épouse, d’une femme éprouvée, d’une actrice de l’histoire et d’une enseignante. Pour la connaître, il faut tenir ces étapes ensemble. Son innocence proclamée dans le Coran n’est pas l’unique contenu d’une vie qui a continué à instruire bien après cette délivrance.`),
 ]},
 'abou-dharr-recherche':{subtitle:'La recherche, l’apprentissage et les exigences d’une conscience',description:'Origines, quête du Prophète, retour vers les Ghifar, vie médinoise, enseignements, séjour en Syrie et mort à ar-Rabadha.',before:[
 section('origines','Un homme des Ghifar avant le voyage',[siyar('abu-dharr','Abu Dharr al-Ghifari','أبو ذر الغفاري'),M('2473a','Récit d’Abu Dharr sur sa famille, sa recherche et son entrée dans l’islam.')],`Abu Dharr appartient aux Ghifar. Les notices donnent plusieurs formes de son nom personnel, dont Jundub ibn Junada, mais c’est sa kunya qui demeure la plus connue. Il ne découvre pas le Prophète depuis une position au centre des familles de Quraysh. Son parcours est celui d’un homme venu d’un autre milieu, qui entend une nouvelle et veut vérifier ce qu’elle signifie avant de l’accepter ou de la répéter.

Dans son récit, transmis par Muslim, il évoque son frère Unays, leur mère, les déplacements et les différends qui précèdent la rencontre du Messager. Ces personnes ne sont pas de simples accessoires d’une quête individuelle. La parole de son frère, qui s’est rendu à La Mecque, met une première information à sa portée. Abu Dharr veut aller plus loin et entendre lui-même celui dont il est question.

Sa recherche le situe parmi les premiers croyants, avant l’installation médinoise. Il ne connaît pas le terme de la route. La prudence, l’attente et les coups reçus appartiennent à ce voyage. Le récit de sa conversion possède ainsi une histoire familiale et géographique : il vient de chez les siens, rencontre un monde où il n’est pas protégé comme un notable et repartira ensuite vers sa propre communauté.

Cette origine éclaire la responsabilité qui lui est confiée après la rencontre. Revenir annoncer ce qu’il a reçu suppose de ne pas garder la foi comme une expérience uniquement personnelle. La suite le conduira plus tard auprès du Prophète à Médine. Son entrée dans l’islam est le début d’une vie d’apprentissage et d’exigence, pas la totalité de ce qu’il laisse à la communauté.`),
 ],after:[
 section('apprendre','Une exigence qui doit aussi se retourner vers soi',[B('30','Abu Dharr rapporte un reproche du Prophète après une insulte visant la mère d’un homme.'),M('1825','Le Prophète explique à Abu Dharr la responsabilité attachée à l’autorité.')],`Après le retour parmi les siens, Abu Dharr rejoint la communauté médinoise. Ses notices le présentent comme un compagnon attaché à la vérité et à une vie dépouillée. Mais ses propres témoignages ne le donnent pas comme un homme qui n’aurait jamais besoin d’être repris. Il raconte avoir insulté quelqu’un en visant sa mère. Le Prophète lui reproche alors une conduite relevant encore de l’ignorance et lui rappelle les devoirs envers ceux que l’on tient sous son autorité.

Al-Marur rencontre ensuite Abu Dharr et un homme à son service portant des vêtements semblables. C’est en réponse à cette observation qu’il rapporte le reproche reçu. La leçon n’est donc pas seulement devenue une phrase qu’il conseille aux autres : elle se lit dans une manière de vêtir et de traiter un autre homme. Le témoignage appelle aussi à ne pas imposer une charge excessive et à aider dans le travail lorsqu’il devient trop lourd.

Un autre jour, Abu Dharr demande une fonction publique. Le Prophète ne lui confie pas cette charge et lui explique qu’elle est un dépôt exigeant, source de regret pour qui n’en remplit pas les obligations. La probité d’un croyant ne signifie donc pas que chaque responsabilité lui convient. La biographie garde cette limite auprès de sa réputation de sincérité. L’aptitude à gouverner n’est pas mesurée par le seul désir de faire le bien.

Ces enseignements donnent une continuité à sa vie. Celui qui a fait un voyage pour chercher la vérité doit ensuite accepter qu’elle corrige ses propres actes et ses souhaits. La fermeté envers le monde perdrait son sens si elle refusait tout examen de soi. Son exemple devient plus concret lorsqu’on le voit recevoir cette éducation, et pas seulement prononcer des avertissements.`),
 section('rabadha','Les biens, le désaccord et les dernières années',[B('1406','Abu Dharr explique à Zayd ibn Wahb son désaccord en Syrie et son installation à ar-Rabadha.'),siyar('abu-dharr','Abu Dharr al-Ghifari','أبو ذر الغفاري')],`Après la mort du Prophète, Abu Dharr continue à transmettre. Son nom reste attaché à la sobriété et à l’avertissement contre l’accumulation des richesses. À l’époque d’Uthman, il séjourne en Syrie et discute avec Muawiya du sens de l’avertissement coranique sur l’or et l’argent thésaurisés. Son propre récit, conservé par al-Bukhari, rapporte le désaccord, la lettre adressée au calife et son retour à Médine.

Beaucoup de personnes viennent alors le voir. Lorsqu’il raconte à Zayd ibn Wahb pourquoi il vit à ar-Rabadha, il expose aussi son échange avec Uthman et la proposition de résider un peu à l’écart. Les représentations de cette fin de vie ont parfois été très chargées politiquement. Le témoignage disponible permet de suivre ce qu’il dit lui-même sans fabriquer les intentions des autres ni effacer le désaccord réel qui l’a conduit de Syrie à Médine.

Les notices situent sa mort à ar-Rabadha en l’an trente-deux de l’Hégire. Il laisse des paroles transmises par de nombreux auditeurs, des avertissements sur les biens et le souvenir d’une vie qui a cherché à réduire la distance entre une conviction et les actes. Son histoire ne s’arrête pas à la rencontre recherchée dans les rues de La Mecque : elle traverse la formation auprès du Messager et les transformations matérielles de la communauté après lui.

La sobriété d’Abu Dharr ne donne pas à chacun le droit de juger toute personne aisée à partir de ses seuls moyens. Le désaccord sur les biens a son texte, son contexte et ses interlocuteurs. En revanche, la biographie laisse une exigence à entendre : ce que l’on reçoit, ce que l’on conserve et ce que l’on demande à ceux qui dépendent de nous engagent réellement notre conduite.`),
 ]},
 'kaab-verite':{subtitle:'Le témoin d’al-Aqaba, le poète et les années après Tabouk',description:'Origines médinoises, engagement d’al-Aqaba, Uhud, poésie, épreuve de Tabouk et transmission dans la famille.',keepParagraphs:3,before:[
 section('origines','Un Médinois engagé avant l’Hégire',[siyar('kaab','Kab ibn Malik','كعب بن مالك'),B('4418','Kab se souvient de son engagement à al-Aqaba et de son absence à Badr.')],`Kab ibn Malik est un Ansari des Banu Salima, parmi les Khazraj de Médine. Son engagement précède l’arrivée du Prophète dans la ville. Il prend part à la rencontre d’al-Aqaba et gardera de cette allégeance un souvenir auquel il attache une grande valeur. Dans le récit de sa vie, ce commencement importe : celui que l’on connaîtra par son absence à Tabouk avait déjà répondu présent dans les premières responsabilités de sa communauté.

Il n’est pas à Badr. Son témoignage précise que cette absence ne lui avait pas été reprochée comme celle qui viendra plus tard : les circonstances du départ n’étaient pas les mêmes. Une biographie chronologique permet de distinguer les deux événements, au lieu de les réunir sous une idée générale de négligence. Les souvenirs d’un compagnon ne doivent pas être aplatis pour produire une morale plus simple que les faits.

Kab participe à Uhud et est connu parmi les poètes qui défendent le Prophète et la communauté. Dans la société de son temps, la poésie n’est pas seulement un plaisir privé ; elle porte la mémoire, la réputation et la réponse publique. Son nom appartient ainsi à la parole engagée bien avant le moment où il devra choisir entre une excuse habile et une réponse vraie.

Les notices racontent aussi les liens qui l’unissent à d’autres compagnons et les blessures d’Uhud, avec des variantes sur certains détails. Le cadre est celui d’une fidélité déjà éprouvée. À Tabouk, il ne se trouve pas au commencement de son histoire : il est un homme disposant d’une expérience, de moyens et d’un passé d’engagement. C’est précisément ce qui rend son propre examen si exigeant lorsqu’il revient sur ce qu’il a laissé échapper.`),
 ],after:[
 section('transmission','Après les cinquante nuits, une vie qui continue',[siyar('kaab','Kab ibn Malik','كعب بن مالك'),B('4418','Kab raconte la promesse de vérité et le bien qu’il veut donner après l’annonce du pardon.')],`L’annonce du pardon n’est pas la dernière journée de Kab. Il décide que sa repentance devra se prolonger dans sa parole et veut consacrer ses biens. Le Prophète lui conseille d’en garder une part. La vérité choisie ne devient donc pas une fuite hors de toutes les responsabilités matérielles : elle entre dans la vie qu’il doit encore mener. Kab dira combien il a voulu rester fidèle à cet engagement de ne pas mentir.

Le récit parvient aux générations suivantes par sa famille, notamment ses fils et ses descendants. Celui qui s’était senti étranger dans les rues de Médine devient le narrateur d’une histoire que d’autres pourront entendre sans avoir traversé ces cinquante nuits. Il ne se donne pas seulement le beau rôle. Il commence par reconnaître ses possibilités, ses retards et les excuses qu’il avait envisagées. C’est l’une des raisons de la force de ce témoignage.

Les notices le retrouvent encore après les premiers califats et rapportent qu’il perd la vue dans la dernière partie de sa vie. Les indications précises sur sa mort ne sont pas toutes identiques. La biographie garde ce dernier temps sans inventer les conversations d’un vieillard ni les pensées qu’il aurait confiées à sa famille. Le dépôt qu’il laisse est déjà clairement identifiable : des paroles poétiques, des souvenirs de la première communauté et un long récit personnel transmis avec sa faute.

Kab ne se résume donc pas à un homme qui a manqué une expédition. Il a participé aux commencements de l’accueil médinois, partagé des épreuves, pris la parole pour les siens et accepté de raconter une défaillance sans se protéger par un mensonge. Son histoire entière permet d’entendre ce que la vérité a changé dans une vie qui possédait un avant et qui a continué après la délivrance.`),
 ]},
 'jabir-attention':{subtitle:'Le fils d’un martyr, le compagnon et l’enseignant de Médine',description:'Origines, al-Aqaba et la famille, mort du père, obligations, vie auprès du Prophète, pèlerinage et transmission.',before:[
 section('origines','Un fils de Médine avant les grands voyages',[siyar('jabir','Jabir ibn Abdullah','جابر بن عبد الله'),B('1351','Souvenir de Jabir au sujet de son père avant Uhud.')],`Jabir ibn Abdullah appartient aux Banu Salima, parmi les Khazraj de Médine. Son père, Abdullah ibn Amr ibn Haram, fait partie des hommes engagés dans l’accueil du Prophète. Les notices associent Jabir, encore jeune, à la seconde rencontre d’al-Aqaba avec son père. L’histoire de ce compagnon commence donc dans une famille médinoise liée aux engagements qui précèdent l’Hégire.

La jeunesse de Jabir implique aussi des obligations. Son père lui demande de rester auprès de ses sœurs pendant certaines expéditions. Le service de la communauté ne se présente pas pour tous sous la même forme au même moment : il faut aussi prendre soin des personnes qui restent. Jabir ne décrit pas ce rôle comme la preuve d’une foi absente. La responsabilité familiale détermine une part de ce qu’il peut faire.

Avant Uhud, Abdullah parle à son fils de ce qu’il laisse, notamment de sa dette et de ses filles. Il meurt au cours de la bataille. Pour Jabir, le deuil ouvre une charge durable. La famille doit être accompagnée et des engagements doivent être honorés. Les témoignages où il cherche ensuite une aide pour la dette de son père prennent leur sens dans cette histoire, et non dans un miracle isolé de toute vie.

Le jeune homme participe ensuite aux événements de la communauté et se marie. La place de ses sœurs intervient dans les explications qu’il donne au Prophète au sujet de son choix matrimonial. Les paroles échangées pendant le voyage du chameau fatigué ne concernent donc pas seulement un voyageur anonyme. Elles rejoignent un fils, un frère et un époux dont le Messager connaît les responsabilités.`),
 ],after:[
 section('pelerinage','Un témoin du pèlerinage et un maître de la génération suivante',[M('1218a','Long témoignage de Jabir sur le pèlerinage du Prophète.'),siyar('jabir','Jabir ibn Abdullah','جابر بن عبد الله')],`Jabir est présent lors de grands rassemblements dont il transmettra ensuite le déroulement. Son récit du pèlerinage du Prophète, conservé dans le recueil de Muslim, devient l’un des témoignages majeurs sur ces rites. Il se souvient des déplacements, des gestes et des enseignements. Ce savoir ne vient pas d’un commentaire imaginé après coup : il est porté par un homme qui a accompagné et observé.

Après la mort du Messager, Jabir continue longtemps à enseigner. Les notices le présentent comme l’un des savants consultés à Médine. Parmi ceux qui rapportent de lui figurent Ata ibn Abi Rabah, Abu az-Zubayr et Muhammad ibn Ali, connu comme al-Baqir. Les générations se rencontrent dans cette transmission : des auditeurs reçoivent de Jabir ce qu’ils n’ont pas vécu eux-mêmes et devront à leur tour le conserver.

La longueur de sa vie donne une portée particulière à son activité. Les personnes qui l’interrogent voient changer les gouvernements, les villes et les usages. Lui garde le souvenir du père mort à Uhud, de la monture qui ralentissait et du pèlerinage accompli auprès du Prophète. La transmission relie ces expériences sans les réduire à un seul registre : la dette, la tendresse, le commerce et l’adoration entrent tous dans le savoir reçu de lui.

Il perd la vue dans ses dernières années. Les auteurs donnent plusieurs indications proches pour sa mort, généralement à la fin des années soixante-dix de l’Hégire, à Médine. Il est alors l’un des derniers témoins d’al-Aqaba. Cette fin de vie replace ses souvenirs dans une durée que l’on oublierait en ne racontant que le chameau ou les dattes. Le jeune fils chargé de sa famille est devenu un maître auquel d’autres viennent demander comment le Messager priait, voyageait et vivait avec les siens.

Sa biographie garde ainsi une continuité : prendre soin, recevoir une attention, observer et transmettre. Les bienfaits qu’il rapporte ne l’arrachent pas aux responsabilités. Ils l’accompagnent dans une vie où la mort d’un père, la présence des sœurs et l’engagement auprès du Prophète restent liés.`),
 ]},
};

export function completeCompanionBiography(book:NarrativeBook):NarrativeBook{
 const e=expansions[book.id];if(!e)return book;
 const additions=[...e.before,...e.middle?.chapters||[],...e.after];
 const sources=new Map(book.sources.map(s=>[s.id,s]));for(const a of additions)for(const s of a.sources)sources.set(s.id,s);
 const existing=book.chapters.map(c=>({...c,scenes:c.scenes.map(s=>({...s,paragraphs:e.keepParagraphs?s.paragraphs.slice(0,e.keepParagraphs):s.paragraphs}))}));
 const at=e.middle?.at??existing.length;
 let chapters=[...e.before.map(a=>a.chapter),...existing.slice(0,at),...e.middle?.chapters.map(a=>a.chapter)||[],...existing.slice(at),...e.after.map(a=>a.chapter)];
 const orders:Record<string,string[]>={
  'ali-proximite':['origines','foyer','etendard','rester','savoir','califat'],
  'uthman-transmission':['origines','donner','califat','copies','questions','siege'],
 };
 const order=orders[book.id];
 if(order){
  if(order.length!==chapters.length||order.some(id=>!chapters.some(c=>c.id===id)))throw Error(`Ordre biographique incomplet : ${book.id}`);
  chapters=order.map(id=>chapters.find(c=>c.id===id)!);
 }
 // Keep the greeting in Khadija's lifetime. Hala's visit belongs to the final
 // chapter, which already recounts it with the other memories after her death.
 if(book.id==='khadija-soutien')chapters=chapters.map(c=>c.id==='demeurer'?{...c,title:'Le salut transmis à Khadija',scenes:c.scenes.slice(0,1)}:c);
 const reordered=!!order||book.id==='khadija-soutien';
 return {...book,version:`${book.id}-biographie-2026-10-24-${reordered?'v4':'v3'}`,subtitle:e.subtitle,scope:{kind:'biography',description:e.description},sources:[...sources.values()],
  editorialNote:`Biographie développée : ${e.description} Les textes religieux, les repères des chroniqueurs et les incertitudes ne sont pas confondus. Aucune traduction moderne ni article de Sirayassira n’est reproduit.`,
  chapters};
}
